// One output item per PDF attachment that matches an account's `match` rules.
// Rules (private-config.json → banks.<key>.match), all case-insensitive:
//   from     – substring of the sender address / display name
//   subject  – regex against the subject
//   filename – regex against the attachment filename
// Empty rules are ignored; every non-empty rule must match. An account with
// no rules never matches. If several accounts match, the one with the most
// rules wins. PDFs that match nothing are dropped.
const accounts = $('Get Accounts').first().json;

const rulesOf = (m = {}) =>
  ['from', 'subject', 'filename'].filter((k) => (m[k] || '').trim() !== '');

function matches(m, mail) {
  const rules = rulesOf(m);
  if (rules.length === 0) return false;
  return rules.every((k) => {
    if (k === 'from') return mail.from.toLowerCase().includes(m.from.trim().toLowerCase());
    return new RegExp(m[k], 'i').test(mail[k]);
  });
}

const out = [];
const emails = $('Gmail Trigger').all();

emails.forEach((item, index) => {
  const j = item.json;
  const fromObj = j.from || {};
  const from = [
    ...(fromObj.value || []).map((v) => `${v.name || ''} <${v.address || ''}>`),
    fromObj.text || '',
    typeof j.from === 'string' ? j.from : '',
    j.From || '',
  ].join(' ');
  const subject = j.subject || j.Subject || '';
  const parsed = new Date(j.date || j.Date || Number(j.internalDate) || Date.now());
  const day = (isNaN(parsed) ? new Date() : parsed).toISOString().slice(0, 10);

  for (const bin of Object.values(item.binary || {})) {
    const original = bin.fileName || 'statement.pdf';
    const isPdf = bin.mimeType === 'application/pdf' || /\.pdf$/i.test(original);
    if (!isPdf) continue;

    const mail = { from, subject, filename: original };
    const hit = Object.entries(accounts)
      .filter(([, a]) => matches(a.match, mail))
      .sort((a, b) => rulesOf(b[1].match).length - rulesOf(a[1].match).length)[0];
    if (!hit) continue;

    const [account, cfg] = hit;
    const folder = (cfg.onedrive_folder || '').replace(/^\/+|\/+$/g, '');
    if (!folder) throw new Error(`Account ${account} has no onedrive_folder in private-config.json`);

    // Banks reuse the same attachment name every month, so prefix the email date.
    let safe = original.replace(/[\\/:*?"<>|#%]/g, '_').trim();
    if (!/\.pdf$/i.test(safe)) safe += '.pdf';
    const fileName = `${day}_${safe}`;
    const uploadPath = [...folder.split('/'), fileName].map(encodeURIComponent).join('/');

    out.push({
      json: { account, folder, fileName, uploadPath, messageId: j.id, subject, from: from.trim() },
      binary: { data: bin },
      pairedItem: { item: index },
    });
  }
});

return out;
